create table if not exists public.platform_onboarding(clinica_id uuid primary key references public.clinicas(id)on delete cascade,stage text not null default'created'check(stage in('created','configuration','team','operational','completed','blocked')),next_action text,owner_id uuid references auth.users(id),due_at timestamptz,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));alter table public.platform_onboarding enable row level security;create policy"plataforma gerencia onboarding"on public.platform_onboarding for all to authenticated using(public.is_platform_admin())with check(public.is_platform_admin());
create or replace function public.platform_onboarding_overview()returns jsonb language plpgsql stable security definer set search_path=public as $$begin if not is_platform_admin()then raise exception'Acesso restrito';end if;return jsonb_build_object('clinics',coalesce((select jsonb_agg(to_jsonb(x)order by x.readiness,x.clinica_nome)from(select c.id clinica_id,c.nome clinica_nome,c.created_at,coalesce(o.stage,'created')stage,o.next_action,o.due_at,(select count(*)from profiles p where p.clinica_id=c.id and p.ativo)team_size,exists(select 1 from configuracoes_clinica cfg where cfg.clinica_id=c.id)has_config,exists(select 1 from tipos_consulta t where t.clinica_id=c.id and t.ativo)has_services,exists(select 1 from agendamentos a where a.clinica_id=c.id)has_activity,((case when exists(select 1 from configuracoes_clinica cfg where cfg.clinica_id=c.id)then 25 else 0 end)+(case when exists(select 1 from tipos_consulta t where t.clinica_id=c.id and t.ativo)then 25 else 0 end)+(case when(select count(*)from profiles p where p.clinica_id=c.id and p.ativo)>1 then 25 else 0 end)+(case when exists(select 1 from agendamentos a where a.clinica_id=c.id)then 25 else 0 end))readiness from clinicas c left join platform_onboarding o on o.clinica_id=c.id)x),'[]'::jsonb));end;$$;
create or replace function public.platform_update_onboarding(p_clinica_id uuid,p_stage text,p_next_action text,p_due_at timestamptz default null)returns void language plpgsql security definer set search_path=public as $$begin if not is_platform_admin()then raise exception'Acesso restrito';end if;if p_stage not in('created','configuration','team','operational','completed','blocked')then raise exception'Status inválido';end if;insert into platform_onboarding(clinica_id,stage,next_action,due_at,updated_by)values(p_clinica_id,p_stage,nullif(trim(p_next_action),''),p_due_at,auth.uid())on conflict(clinica_id)do update set stage=excluded.stage,next_action=excluded.next_action,due_at=excluded.due_at,updated_at=now(),updated_by=auth.uid();end;$$;revoke all on function public.platform_onboarding_overview(),public.platform_update_onboarding(uuid,text,text,timestamptz)from public,anon;grant execute on function public.platform_onboarding_overview(),public.platform_update_onboarding(uuid,text,text,timestamptz)to authenticated;
